import json, hashlib
from pathlib import Path
root=Path.cwd()
def read(p): return json.loads((root/p).read_text(encoding='utf-8-sig'))
def ref(p): return {'path':p,'sha256':hashlib.sha256((root/p).read_bytes()).hexdigest()}
s=read('work/consumer-execution/SPECIALIST-RESULT.json'); o=read(s['operation_result']['path']); e=read(s['execution_report']['path']); c=read(o['artifacts']['check.json']['path']); cap=read(o['artifacts']['capture/capture.json']['path']); imp=read(o['import_result'])
fail=[]; checked=[]
def walk(v):
 if isinstance(v,dict):
  if isinstance(v.get('path'),str) and isinstance(v.get('sha256'),str):
   p=v['path']
   if (root/p).is_file():
    checked.append(p)
    if ref(p)['sha256']"'!=v['"'sha256']: fail.append(p)
   else: fail.append('missing:'+p)
  for x in v.values(): walk(x)
 elif isinstance(v,list):
